entries./**\n * @brief Mark a range as deleted o:
/**
 * @brief 将某段地址范围标记为已删除或无效（TRIM / discard）
 *
 * 通知设备或 FTL 该地址范围已不再需要。在空间被回收前，数据可能仍可读；其行为类似于 SSD 上的 TRIM 或 eMMC 上的 discard。当调用方要求读取该范围时返回设备擦除后的默认值时，请使用 @ref ESP_BLOCKDEV_CMD_ERASE_CONTENTS。
 *
 * 参数：指向 @ref esp_blockdev_cmd_arg_erase_t 的指针。
 *
 * @code{c}
 * esp_blockdev_cmd_arg_erase_t arg = {
 *     .start_addr = aligned_start,
 *     .erase_len = aligned_len,
 * };
 * esp_err_t ret = bdl->ops->ioctl(bdl, ESP_BLOCKDEV_CMD_MARK_DELETED, &arg);
 * @endcode
 */

entries./**\n * @brief Erase a range and set con:
/**
 * @brief 擦除一段地址范围并将其内容设为擦除后的默认值
 *
 * 执行擦除（或等效操作），使读取该范围时返回设备擦除后的默认值（参见 @ref esp_blockdev_flags_t 中的 @c default_val_after_erase 字段）。该操作比 @ref ESP_BLOCKDEV_CMD_MARK_DELETED 更严格，后者仅从转换层视角使数据失效。
 *
 * 参数：指向 @ref esp_blockdev_cmd_arg_erase_t 的指针。
 *
 * @code{c}
 * esp_blockdev_cmd_arg_erase_t arg = {
 *     .start_addr = aligned_start,
 *     .erase_len = aligned_len,
 * };
 * esp_err_t ret = bdl->ops->ioctl(bdl, ESP_BLOCKDEV_CMD_ERASE_CONTENTS, &arg);
 * @endcode
 */
